mapper.select:
SELECT j.id, pr.name as project, j.name, j.version, a.nickname as creator, am.nickname as modifier, DATE_FORMAT(j.changed_on, '%Y-%m-%d %H:%i:%s') as modified, j.expand, i.name as imageName FROM job_template j LEFT JOIN project pr ON j.project_id = pr.id LEFT JOIN ab_user a ON j.created_by_fk = a.id LEFT JOIN ab_user am ON j.changed_by_fk = am.id LEFT JOIN images i ON j.images_id = i.id
AND j.biz_project_id = #{bizProjectId}
AND j.biz_project_id = 1
AND j.project_id = #{projectId}
AND a.nickname LIKE CONCAT('%', #{creator}, '%')
AND am.nickname LIKE CONCAT('%', #{modifier}, '%')
AND j.version LIKE CONCAT('%', #{version}, '%')
AND j.images_id = #{imagesId}
ORDER BY j.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT j.id) FROM job_template j LEFT JOIN project pr ON j.project_id = pr.id LEFT JOIN ab_user a ON j.created_by_fk = a.id LEFT JOIN ab_user am ON j.changed_by_fk = am.id
AND j.biz_project_id = #{bizProjectId}
AND j.biz_project_id = 1
AND j.project_id = #{projectId}
AND a.nickname LIKE CONCAT('%', #{creator}, '%')
AND am.nickname LIKE CONCAT('%', #{modifier}, '%')
AND j.version LIKE CONCAT('%', #{version}, '%')
AND j.images_id = #{imagesId}
